                                    "Invalid route {path_str:?}: parameters must be registered with a name"
                                )
                                .into());
                            }
                            InsertError::InvalidCatchAll => {
                                return Err(format!(
                                    "Invalid route {path_str:?}: catch-all parameters are only allowed at the end of a route"
                                )
                                .into());
                            }
                            other => {
                                return Err(format!("Invalid route {path_str:?}: {other}").into());
                            }
                        },
                    }
                }
            }
